def _py_tree_filter_ignored(candidates: list[str]) -> list[str]:
    """Remove gitignored paths from candidates using a single batched subprocess call."""
    if not candidates:
        return []
    try:
        proc = subprocess.run(
            ["git", "check-ignore", "--stdin", "--no-index"],
            input="\n".join(candidates),
            capture_output=True,
            text=True,
            cwd=str(REPO_ROOT),
            timeout=30,
        )
        ignored = set(proc.stdout.splitlines())
        return [c for c in candidates if c not in ignored]
    except (subprocess.SubprocessError, OSError):
        return candidates


def _py_tree_render(shown: list[str]) -> str:
    """Render a list of relative .py paths as an indented tree string."""
    tree_lines: list[str] = []
    for rel in shown:
        parts = rel.split("/")
        indent = "    " * (len(parts) - 1)
        tree_lines.append(f"{indent}└── {parts[-1]}")
    return "\n".join(tree_lines)


def _py_tree() -> str:
